    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
    flex-shrink: 0;
}

.avatar-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    color: #adb5bd;
    font-size: 0.75rem;
}

/* ── Toast ── */
.settings-toast {
    position: sticky;
    top: 0;
    z-index: 100;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-weight: 500;
    animation: slideDown 0.25s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ── Live Preview ── */
.live-preview {
    border-radius: 0.5rem;
    border: 1px solid #dee2e6;
    transition: all 0.2s ease;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #212529;
    color: #f8f9fa;
    border-color: #495057;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #212529 50%);
    color: #495057;
}

/* ── Modal backdrop fix ── */
::deep .modal-backdrop {
    position: fixed;
}

::deep .modal {
    position: fixed;
}

/* ── Table tweaks ── */
.table th {
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: #6c757d;
}
